INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('2e417244-81d1-4775-8b51-3fe35d694add','dshx-0-2-0-preview-0','published','0.2.0-preview.0','DSHX · create-dshx','preview','2026-10-20','{"en":{"title":"DSHX 0.2: plugin tooling for DeepSeek Harness 0.2","description":"DSHX 0.2.0-preview.0 follows DeepSeek Harness 0.2 with a protocol-2 adapter, new settings and conversation APIs, peer-based RPC, session format 4, and a migration guide for plugin authors.","sections":[{"id":"new-protocol-line","title":"A new compatibility line","paragraphs":["DSHX 0.2.0-preview.0 moves the public line to DeepSeek Harness 0.2. The release ships a protocol-2 adapter and drops the protocol-1 adapter, so a plugin must declare a 0.2-compatible DSH range before it can build or run.","The adapter was verified against a source build of the dsh-v0.2.1-rc.2 tag. The npm artifact published as DeepSeek Harness 0.2.1-rc.2 remains experimental until upstream republishes it; DSHX reports that distinction instead of treating a version number as proof of runtime compatibility."]},{"id":"settings-and-conversation","title":"Settings and conversation use the 0.2 APIs","items":["The old Host settings provider and defineSettings API are replaced by a plugin Config schema projected through DSH SettingsForms. Client settings read ctx.configForms by the Host profile entry id.","Conversation contributions register through ctx.uiConversation.events.register. Types move to @deepseek-ai/dsh-client-ui-conversation/client, and @deepseek-ai/dsh-client-runtime is no longer used.","Session data follows format 4, including the new event vocabulary and branded sequence values."]},{"id":"connection-tools-manifests","title":"Connection, tools, and manifests","items":["Host APIs register peer-based handlers with connection.rpc.handle. The authority option is gone, and Client code reaches the Host through ctx.remote namespaces.","Tool contributions use the PTC runtime, ToolCallId, and JsonValue types from the 0.2 packages.","Manifest validation now reads engines.dsh, requires manifestVersion 1, accepts array-valued bundle.patch, and rejects the removed /invariant entry.","DSH 0.2 does not expose a runtime Slot catalog. dshx inspect slots reports DSHX3204, and the UI scaffold accepts explicit --slot and --provider values with a verification warning."]},{"id":"migration-and-availability","title":"Migration and availability","paragraphs":["create-dshx, the Phase A fixture, and the reference marketplace plugin are updated to the 0.2 line. The migration guide collects the API changes, the new entry-id behavior for settings, and the steps to rebuild a plugin against DSH 0.2.","DSHX and create-dshx are published as 0.2.0-preview.0 on npm''s preview channel. The stable latest channel remains on 0.1.3."]}],"links":[{"label":"DSHX 0.2.0-preview.0 on npm","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.2.0-preview.0"},{"label":"create-dshx 0.2.0-preview.0 on npm","href":"https://www.npmjs.com/package/create-dshx/v/0.2.0-preview.0"},{"label":"0.1 to 0.2 migration guide","href":"https://dshx.io/en/docs/compatibility#migration"},{"label":"Release commit on GitHub","href":"https://github.com/liyown/dshx/commit/eea4bdb475181f3f777d43672aa4f2b8268ead53"}]},"zh":{"title":"DSHX 0.2：适配 DeepSeek Harness 0.2 的插件工具链","description":"DSHX 0.2.0-preview.0 跟进 DeepSeek Harness 0.2，改用 protocol-2 适配器，并更新 Settings、Conversation、RPC 与 Session 格式，同时提供插件作者迁移指南。","sections":[{"id":"new-protocol-line","title":"进入新的兼容线","paragraphs":["DSHX 0.2.0-preview.0 把公开发布线推进到 DeepSeek Harness 0.2。本次发布提供 protocol-2 适配器，并移除 protocol-1 适配器；插件需要声明兼容 0.2 的 DSH 版本范围，才能继续构建和运行。","适配器使用 dsh-v0.2.1-rc.2 标签的源码构建完成验证。npm 上以 0.2.1-rc.2 发布的产物在上游重新发布前仍标记为实验性；DSHX 会区分这类状态，不把版本号本身当作真实运行时兼容的证明。"]},{"id":"settings-and-conversation","title":"Settings 与 Conversation 改用 0.2 接口","items":["旧的 Host settings provider 与 defineSettings 接口被插件 Config schema 取代，由 DSH SettingsForms 呈现。Client 通过 ctx.configForms，以 Host profile 的 entry id 读取设置。","Conversation 贡献改用 ctx.uiConversation.events.register 注册。类型迁移到 @deepseek-ai/dsh-client-ui-conversation/client，不再依赖 @deepseek-ai/dsh-client-runtime。","Session 数据采用 format 4，包括新的会话事件词汇与品牌化序列值。"]},{"id":"connection-tools-manifests","title":"连接、工具与清单","items":["Host API 通过 connection.rpc.handle 注册基于 peer 的处理器。authority 选项已移除，Client 通过 ctx.remote 命名空间访问 Host。","工具贡献使用 PTC runtime、ToolCallId，以及 0.2 包提供的 JsonValue 类型。","清单校验改为读取 engines.dsh，要求 manifestVersion 1，允许 bundle.patch 使用数组，并拒绝已移除的 /invariant 入口。","DSH 0.2 不提供运行时 Slot 目录。dshx inspect slots 会返回 DSHX3204；UI 脚手架改为接受显式 --slot 与 --provider 参数，并给出验证警告。"]},{"id":"migration-and-availability","title":"迁移与获取方式","paragraphs":["create-dshx、Phase A fixture 与参考 marketplace 插件都已更新到 0.2 线。迁移指南整理了 API 变化、settings 的 entry id 语义，以及基于 DSH 0.2 重新构建插件的步骤。","DSHX 与 create-dshx 已以 0.2.0-preview.0 发布到 npm 的 preview 通道，稳定 latest 通道仍为 0.1.3。"]}],"links":[{"label":"npm 上的 DSHX 0.2.0-preview.0","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.2.0-preview.0"},{"label":"npm 上的 create-dshx 0.2.0-preview.0","href":"https://www.npmjs.com/package/create-dshx/v/0.2.0-preview.0"},{"label":"0.1 到 0.2 迁移指南","href":"https://dshx.io/en/docs/compatibility#migration"},{"label":"GitHub 发布提交","href":"https://github.com/liyown/dshx/commit/eea4bdb475181f3f777d43672aa4f2b8268ead53"}]}}') ON CONFLICT(slug) DO NOTHING;
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('0f5a0005-fd0c-4b30-a2c9-f319ce35a90a','hub-cli-0-1-3-preview-0','published','0.1.3-preview.0','Hub CLI','preview','2026-10-20','{"en":{"title":"Hub CLI 0.1.3: a prompt that stays out of the package","description":"Hub CLI 0.1.3-preview.0 moves the operations prompt to an administrator-only bundle, keeps provider resources encrypted, and lets each run pick up the current prompt and CLI version.","sections":[{"id":"why-the-prompt-moved","title":"Why the prompt moved","paragraphs":["The operations prompt changes more often than the CLI. Bundling it in the public package meant every guidance update required a new npm release, and an operator could silently run an older prompt.","The prompt now lives in the Hub. An administrator reviews it at the administrator prompt page; the operations Agent fetches the current prompt, metadata, and allowlisted resources with dshx-hub ops bundle."]},{"id":"administrator-changes","title":"What changed for administrators","items":["The bundle endpoint requires an administrator bearer token. A regular catalog token is not enough.","Stored resources use AES-GCM encryption and are returned only inside an authenticated bundle. The bundle file is written with mode 0600.","The public CLI no longer includes prompt files, and the old ops prompt command is gone."]},{"id":"operator-changes","title":"What changed for the operator","items":["The bootstrap stays on the stable preview channel and converges on the bundle''s expected CLI version.","If the installed CLI and the bundle disagree, agent_bundle_mismatch reports expectedCliVersion so the next run can install the matching version and retry.","The prompt continues to require ops begin, per-write run IDs, checkpoints, and verification before ops finish."]},{"id":"availability","title":"Availability","paragraphs":["Hub CLI 0.1.3-preview.0 is available on npm''s preview channel. The stable latest channel remains on 0.1.1."]}],"links":[{"label":"Hub CLI 0.1.3-preview.0 on npm","href":"https://www.npmjs.com/package/@becomeopc/dshx-hub-cli/v/0.1.3-preview.0"},{"label":"Hub CLI release notes","href":"https://github.com/liyown/dshx/blob/main/packages/framework-hub-cli/CHANGELOG.md"}]},"zh":{"title":"Hub CLI 0.1.3：运营提示词不再随包分发","description":"Hub CLI 0.1.3-preview.0 把运营提示词移至管理员专属 bundle，凭据加密保存，并让每轮运营自动获取当前提示词与 CLI 版本。","sections":[{"id":"why-the-prompt-moved","title":"为什么把提示词移出 CLI","paragraphs":["运营提示词的更新频率高于 CLI。此前把它打进公开包，意味着每次调整规则都要重新发布 npm 版本，而运营端也可能在不知情时继续使用旧提示词。","现在提示词保存在 Hub 中。管理员在管理员提示词页面审阅内容，运营 Agent 通过 dshx-hub ops bundle 获取当前提示词、元数据和允许使用的资源。"]},{"id":"administrator-changes","title":"管理员侧的变化","items":["bundle 接口要求管理员 bearer token，普通 catalog token 不足以读取。","保存的资源使用 AES-GCM 加密，只在通过认证的 bundle 中返回；bundle 文件权限为 0600。","公开 CLI 不再包含提示词文件，旧的 ops prompt 命令已移除。"]},{"id":"operator-changes","title":"运营侧的变化","items":["引导脚本固定在 preview 通道，并以 bundle 声明的 CLI 版本为准收敛。","如果本地 CLI 与 bundle 不一致，agent_bundle_mismatch 会返回 expectedCliVersion，下一轮可以安装匹配版本后重试。","提示词仍然要求先运行 ops begin，每次写入携带 run ID，使用 checkpoint，并在 ops finish 前完成验证。"]},{"id":"availability","title":"获取方式","paragraphs":["Hub CLI 0.1.3-preview.0 已发布到 npm 的 preview 通道，稳定 latest 通道仍为 0.1.1。"]}],"links":[{"label":"npm 上的 Hub CLI 0.1.3-preview.0","href":"https://www.npmjs.com/package/@becomeopc/dshx-hub-cli/v/0.1.3-preview.0"},{"label":"Hub CLI 发布记录","href":"https://github.com/liyown/dshx/blob/main/packages/framework-hub-cli/CHANGELOG.md"}]}}') ON CONFLICT(slug) DO NOTHING;
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('d4fedc20-8fd2-49a8-a591-a35f2953fdfa','hub-editorial-blog-and-featured-shelves','published','2026.10','DSHX Hub','release','2026-10-20','{"en":{"title":"A plugin journal and curated shelves for DeepSeek Harness","description":"DSHX Hub now publishes bilingual editorial articles and per-category featured shelves, giving plugin discovery a path beyond search results and flat category lists.","sections":[{"id":"editorial-articles","title":"Editorial articles","paragraphs":["The new blog publishes longer-form writing about the DeepSeek Harness plugin ecosystem: how a plugin is evaluated, how a category is changing, and what a particular tool is good for. Articles are stored in D1, edited in the admin area, and rendered in English and Chinese.","The launch articles look at the work of curating 52 plugins and at a DeepSeek balance widget for the DSH Web interface."]},{"id":"curated-shelves","title":"Curated shelves","paragraphs":["Featured shelves are ordered picks inside a category. They give editors a way to explain a short list instead of relying only on recency or star counts. Empty shelves are cleared rather than left with stale entries."]},{"id":"built-for-discovery","title":"Built for discovery","items":["Both surfaces publish localized pages with canonical URLs, hreflang alternates, and sitemap entries.","Articles and shelves link to plugin pages, so readers can move from an explanation to the install target.","The Hub API exposes the same content to agents, keeping the public site and automated curation in sync."]},{"id":"where-to-start","title":"Where to start","paragraphs":["The journal and the featured shelves are linked from the main navigation. Start with the plugin curation article or browse the current shelves by category."]}],"links":[{"label":"Read the DSHX Hub journal","href":"https://dshx.io/en/blog"},{"label":"Browse featured plugins","href":"https://dshx.io/en/featured"},{"label":"Curating 52 DeepSeek Harness plugins","href":"https://dshx.io/en/blog/curating-52-deepseek-harness-plugins"},{"label":"The DSH whale widget guide","href":"https://dshx.io/en/blog/dsh-whale-widget-guide"}]},"zh":{"title":"DSHX Hub 新增插件博客与分类精选榜单","description":"DSHX Hub 新增双语编辑博客与按分类整理的精选榜单，让 DeepSeek Harness 插件的发现不再只依赖搜索和分类列表。","sections":[{"id":"editorial-articles","title":"编辑博客","paragraphs":["新的博客用于发布较长的插件生态文章：一个插件如何评估、某个分类正在发生什么变化，以及某个工具适合解决什么问题。文章存储在 D1，通过管理后台编辑，并以中英文呈现。","首批文章分别讨论 52 个插件的整理过程，以及 DSH Web 界面里的 DeepSeek 余额挂件。"]},{"id":"curated-shelves","title":"分类精选榜单","paragraphs":["精选榜单是分类内按顺序排列的人工推荐。它让编辑可以解释一份短名单，而不必只依赖更新时间或 star 数。没有有效推荐的榜单会被清空，而不是保留过期条目。"]},{"id":"built-for-discovery","title":"为发现而设计","items":["博客与榜单都提供本地化页面、canonical、hreflang 与 sitemap 条目。","文章和榜单会链接到插件页面，读者可以从说明直接进入安装目标。","Hub API 向 Agent 暴露同样的内容，让公开站点与自动运营保持一致。"]},{"id":"where-to-start","title":"从哪里开始","paragraphs":["博客与精选榜单已加入主导航。可以先读 52 个插件的整理记录，或按分类浏览当前榜单。"]}],"links":[{"label":"阅读 DSHX Hub 博客","href":"https://dshx.io/en/blog"},{"label":"浏览精选插件","href":"https://dshx.io/en/featured"},{"label":"52 个 DeepSeek Harness 插件的整理记录","href":"https://dshx.io/en/blog/curating-52-deepseek-harness-plugins"},{"label":"DSH 鲸鱼余额挂件指南","href":"https://dshx.io/en/blog/dsh-whale-widget-guide"}]}}') ON CONFLICT(slug) DO NOTHING;
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('5830d4b2-af46-4248-958b-4b79d22d6e9e','hub-daily-operations-reports','published','2026.10','DSHX Hub','release','2026-10-21','{"en":{"title":"A public daily log of plugin catalog operations","description":"DSHX Hub now publishes a bilingual report for each operations day: the research, plugins changed, verification, and open items. Reports render as Markdown and merge same-day runs.","sections":[{"id":"one-page-per-day","title":"One page per day","paragraphs":["The operations log used to list each run separately. It now groups reports by the Asia/Shanghai calendar day, with a stable URL such as /operations/2026-10-21. Older run-based links redirect to the day page.","Each day shows the run count, the latest completion time, and the plugins touched during the day."]},{"id":"what-reports-contain","title":"What the reports contain","items":["The priorities and sources the operator chose, so a quiet day is distinguishable from an unexecuted query.","Confirmed metadata and copy changes, with links to the affected plugin pages.","Material unfinished work, errors, and the evidence used to decide what to do next."]},{"id":"markdown-and-merging","title":"Markdown and same-day merging","paragraphs":["Reports are written in GitHub-Flavored Markdown: headings, short lists, links, and tables render as reader-friendly pages instead of plain text. Raw HTML and remote images are not rendered.","When a later run publishes on the same day, the operator merges the earlier report into one cumulative document. The Hub detects the merge marker and hides superseded notes; reports published before the merge guidance remain available in a collapsed section."]},{"id":"why-public","title":"Why make it public","paragraphs":["The log is a transparency record for a catalog that is assembled and maintained by an autonomous operator. It also gives readers and other agents a concrete view of how plugin selection, localization, and verification actually happen."]}],"links":[{"label":"Browse the operations log","href":"https://dshx.io/en/operations"},{"label":"Read the latest daily report","href":"https://dshx.io/en/operations/2026-10-21"},{"label":"DSHX Hub journal","href":"https://dshx.io/en/blog"}]},"zh":{"title":"DSHX Hub 公开每日插件目录运营日报","description":"DSHX Hub 现在按天发布双语运营日报，记录调研、插件变更、验证与未完成事项；正文使用 Markdown，并按天合并同日运行。","sections":[{"id":"one-page-per-day","title":"每天一个页面","paragraphs":["运营日志过去按每次运行分别列出。现在它按 Asia/Shanghai 日历日聚合，并提供稳定地址，例如 /operations/2026-10-21。旧的按运行划分的链接会重定向到当天页面。","每天页面会显示运行次数、最后完成时间，以及当天涉及的插件。"]},{"id":"what-reports-contain","title":"日报包含什么","items":["运营 Agent 选择的优先事项与信息来源，让没有产出的日子与没有执行的查询可以区分。","已确认的元数据与文案改动，并链接到受影响的插件页面。","实质性的未完成事项、错误，以及决定下一步所依据的证据。"]},{"id":"markdown-and-merging","title":"Markdown 与同日合并","paragraphs":["日报使用 GitHub-Flavored Markdown 编写，标题、短列表、链接和表格会渲染成易读页面，而不是纯文本。原始 HTML 与远程图片不会渲染。","同一天后续运行发布时，运营 Agent 会把更早的日报合并成一份累计文档。Hub 识别合并标记后隐藏被取代的记录；在合并规则启用前发布的日报仍保留在折叠区域。"]},{"id":"why-public","title":"为什么公开","paragraphs":["对于由自动运营 Agent 持续整理和维护的插件目录，这份日志是一份透明度记录。它也让读者和其他 Agent 能具体看到插件筛选、本地化与验证实际如何发生。"]}],"links":[{"label":"浏览运营日报","href":"https://dshx.io/en/operations"},{"label":"阅读最新日报","href":"https://dshx.io/en/operations/2026-10-21"},{"label":"DSHX Hub 博客","href":"https://dshx.io/en/blog"}]}}') ON CONFLICT(slug) DO NOTHING;
